// Shared helpers for the fake provider CLIs in scripts/ci/fakes. The Windows tests (WindowsProviderTests,
// WindowsRunTests) and the `windows` CI job put that folder first on PATH, so `claude`, `copilot`, `az` and `aws`
// resolve to these fakes through ProcessLauncher exactly as the real tools would.
'use strict';
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

// Every line ends with CR LF, as Windows programs often write them: the providers must cope.
const EOL = '\r\n';

/** Appends {tool, argv, cwd} as one JSON line to FAKE_ARGV_LOG when it is set, so tests can check the exact arguments. */
function record(tool, argv) {
  const file = process.env.FAKE_ARGV_LOG;
  if (file) fs.appendFileSync(file, JSON.stringify({ tool, argv, cwd: process.cwd() }) + '\n');
}

/** The value after `name` in argv, or undefined. */
function option(argv, name) {
  const i = argv.indexOf(name);
  return i >= 0 ? argv[i + 1] : undefined;
}

/**
 * Starts a child node process that sleeps, writes "<own pid> <child pid>" to FAKE_PID_FILE (or ./fake-pids.txt) and
 * then waits forever. Cancelling the run must stop both: this is the process tree a real CLI leaves behind.
 */
function sleepTree() {
  const pidFile = process.env.FAKE_PID_FILE || path.join(process.cwd(), 'fake-pids.txt');
  const child = spawn(process.execPath, ['-e', 'setInterval(() => {}, 1000)'], { stdio: 'ignore' });
  child.on('spawn', () => fs.writeFileSync(pidFile, `${process.pid} ${child.pid}\n`));
  setInterval(() => {}, 1000);
}

module.exports = { EOL, record, option, sleepTree };
